            .{
                .id = "MS:1000079",
                .name = "fourier transform ion cyclotron resonance",
                .obsolete = false,
                .definition = .{
                    .value = "A device based on the principle of ion cyclotron resonance in which an ion in a magnetic field moves in a circular orbit at a frequency characteristic of its m/z value. Ions are coherently excited to a larger radius orbit using a pulse of radio frequency energy and their image charge is detected on receiver plates as a time domain signal. Fourier transformation of the time domain signal results in a frequency domain signal which is converted to a mass spectrum based in the inverse relationship between frequency and m/z.",
                    .suffix = "[PSI:MS]",
                },
                .synonyms = &.{
                    .{
                        .value = "FT_ICR",
                        .suffix = "EXACT []",
                    },
                },
                .alternate_ids = &.{},
                .replaced_by = &.{},
