            .{
                .id = "MS:1003357",
                .name = "ANN-SoLo",
                .obsolete = false,
                .definition = .{
                    .value = "ANN-SoLo (Approximate Nearest Neighbor Spectral Library) is a spectral library search engine for fast and accurate open modification searching. ANN-SoLo uses approximate nearest neighbor indexing to speed up open modification searching by selecting only a limited number of the most relevant library spectra to compare to an unknown query spectrum. This is combined with a cascade search strategy to maximize the number of identified unmodified and modified spectra while strictly controlling the false discovery rate and the shifted dot product score to sensitively match modified spectra to their unmodified counterpart.",
                    .suffix = "[doi:10.1021/acs.jproteome.8b00359, doi:10.1021/acs.jproteome.9b00291]",
                },
                .synonyms = &.{},
                .alternate_ids = &.{},
                .replaced_by = &.{},
                .consider = &.{},
                .parents = &.{
                    "MS:1001456",
                },
                .relationships = &.{},
                .xrefs = &.{},
                .fields = &.{
                    .{
                        .tag = "id",
                        .value = "MS:1003357",
                    },
                    .{
                        .tag = "name",
                        .value = "ANN-SoLo",
                    },
                    .{
                        .tag = "def",
                        .value = "\"ANN-SoLo (Approximate Nearest Neighbor Spectral Library) is a spectral library search engine for fast and accurate open modification searching. ANN-SoLo uses approximate nearest neighbor indexing to speed up open modification searching by selecting only a limited number of the most relevant library spectra to compare to an unknown query spectrum. This is combined with a cascade search strategy to maximize the number of identified unmodified and modified spectra while strictly controlling the false discovery rate and the shifted dot product score to sensitively match modified spectra to their unmodified counterpart.\" [doi:10.1021/acs.jproteome.8b00359, doi:10.1021/acs.jproteome.9b00291]",
                    },
                    .{
                        .tag = "is_a",
                        .value = "MS:1001456",
                    },
                },
            },
