            .{
                .id = "MS:1003907",
                .name = "parallel reaction monitoring",
                .obsolete = false,
                .definition = .{
                    .value = "Parallel Reaction Monitoring (PRM) utilizes high-resolution, accurate-mass mass spectrometry, typically a quadrupole orbitrap or quadrupole time-of-flight instrument, to isolate specific precursor ions and detect all resulting product ions in parallel. Unlike Selected Reaction Monitoring (SRM), which filters for pre-selected transitions, PRM acquires full MS/MS spectra for each target, thereby eliminating the need for transition optimization and providing high specificity through high-resolution interference rejection.",
                    .suffix = "[PSI:MS]",
                },
                .synonyms = &.{
                    .{
                        .value = "PRM",
                        .suffix = "EXACT []",
                    },
                },
                .alternate_ids = &.{},
